import sys

def min_coupons(N, trips):
    INF = float('inf')
    dp = [[INF] * 11 for _ in range(10001)]
    dp[0][0] = 0

    for t, z in trips:
        for s in range(10001):
            if dp[s][z] == INF:
                continue
            for nz in range(11):
                cost = 2 + abs(z - nz)
                if s + 10000 >= t:
                    dp[t][nz] = min(dp[t][nz], dp[s][z] + cost)
                else:
                    dp[s + 10000][nz] = min(dp[s + 10000][nz], dp[s][z] + cost)

    return min(dp[-1])

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    N = int(data[0])
    trips = []
    index = 1
    for _ in range(N):
        Z = int(data[index])
        T = int(data[index + 1])
        trips.append((T, Z))
        index += 2

    result = min_coupons(N, trips)
    print(result)

if __name__ == "__main__":
    main()
